inputs = ['fv', 'hfiv', 'fb', 'vjexa', 'dbh']
outputs = ['eixi', 'heyiaeixi', 'eix', 'ixijexia', 'dixh']

print("Input strings:")
for i, inp in enumerate(inputs):
    print(f"  {i}: '{inp}'")

print("\nOutput strings:")
for i, out in enumerate(outputs):
    print(f"  {i}: '{out}'")

print("\nChanged pairs (where input != output):")
for i in range(len(inputs)):
    if inputs[i] != outputs[i]:
        print(f"  {i}: '{inputs[i]}' -> '{outputs[i]}'")

